#!/usr/bin/env python3
"""SBTL_HUB Stage-only native 0.0D + 0.0C V4 gate (no cards, no production writes).
Compressed payload is a PUBLIC MINIMAL PROJECTION of candidate IDs and 0.0C routing.
Confidential source bodies/headlines/URLs remain only in user-owned Drive.
"""
from pathlib import Path
import os,sys,json,hashlib,base64,gzip,subprocess,textwrap
MAIN='805c2718d6daf40a219ae94242d9687e33ac3e88'
FULL='07a91714e56be2a8bfad10ab63822f0c5cb3f06e'
LEAN='8ebad37e98639ad97a30e52063d7325da77be650'
PAYLOAD_SHA256='84db797a9d0bbb1a1b343d18ba935aec4fcc8ba35e06757a2d32090234bd7b30'
PAYLOAD_B64=''
ROOT=Path(__file__).resolve().parent.parent
RUN=ROOT/'runs/2026-10-26/stage0c-selector-entry'
STAGE_PATH=RUN/'STAGE_0_0C_V4_GATE_MINIMAL_PUBLIC_PROJECTION_20261026.json'
DOCREF='runs/2026-10-24/r37-native-0-0d-evidence/R37_0_0D_V4_STAGE_20261024.json'

def git(*args):
 p=subprocess.run(['git',*args],cwd=ROOT,capture_output=True,text=True,timeout=90)
 if p.returncode:raise RuntimeError(f"git {' '.join(args)}: {p.stderr[-1000:]}")
 return p.stdout.strip()


def main():
 assert git('rev-parse',f'{MAIN}:data/cards.full.json') == FULL, 'Full blob changed'
 assert git('rev-parse',f'{MAIN}:public/data/cards.json') == LEAN, 'Lean blob changed'
 assert git('show',f'{MAIN}:scripts/validate_card_run_v4_hardening.mjs').startswith('#!/usr/bin/env node')
 # This payload contains NO source story titles, confidential excerpts or original raw URLs.
 compact=gzip.decompress(base64.b64decode(PAYLOAD_B64))
 assert hashlib.sha256(compact).hexdigest()==PAYLOAD_SHA256
 j=json.loads(compact)
 assert j['status']=='PASS' and j['stage']=='0.0C'
 assert j['base_full_blob_sha']==FULL and j['base_main_commit_sha']==MAIN
 assert j['document_universe_manifest_ref']==DOCREF
 assert len(j['original_input_ledger'])==1313 and len(j['source_universe_expansion_ledger'])==1330
 assert len(j['terminal_discovery_disposition_ledger'])==1330
 assert len(j['regional_coverage_matrix'])==6 and len(j['topic_coverage_matrix'])==14
 assert all(set(r)=={'candidate_id','discovery_origin'} for r in j['original_input_ledger'])
 ids=[x['candidate_id'] for x in j['source_universe_expansion_ledger']]
 tid=[x['candidate_id'] for x in j['terminal_discovery_disposition_ledger']]
 assert len(set(ids))==1330 and len(set(tid))==1330 and set(ids)==set(tid)
 RUN.mkdir(parents=True,exist_ok=True)
 STAGE_PATH.write_text(json.dumps(j,ensure_ascii=False,indent=2,sort_keys=True)+'\n',encoding='utf-8')
 # Native locked-main validator functions, no copied/re-written policy logic.
 src=(ROOT/'scripts/validate_card_run_v4_hardening.mjs').read_text(encoding='utf-8')
 original=git('show',f'{MAIN}:scripts/validate_card_run_v4_hardening.mjs')
 assert src.rstrip()==original.rstrip(), 'Stage-only native must use unchanged current-main source'
 assert 'const args = process.argv.slice(2);' in src
 material=src.split('const args = process.argv.slice(2);',1)[0]+'\nexport { validateDocumentUniverse, validateCoverage };\n'
 exported=ROOT/'scripts/.stage0c_selector_gate_unchanged_main_export.mjs'
 harness=ROOT/'scripts/.stage0c_selector_gate_harness.mjs'
 try:
  exported.write_text(material,encoding='utf-8')
  harness.write_text('import { readFileSync, writeFileSync, rmSync } from "node:fs";\nimport { resolve } from "node:path";\nimport {validateDocumentUniverse, validateCoverage} from "./.stage0c_selector_gate_unchanged_main_export.mjs";\nconst run=JSON.parse(readFileSync(process.argv[2],"utf8"));\nconst root=".";\nconst ok=(label,fn)=>{try{fn();console.log("PASS "+label)}catch(e){console.error(e.code,e.message);process.exitCode=1}};\nok("0.0D manifest native current-main",()=>validateDocumentUniverse(run,root));\nok("0.0C full 1330 identity+matrix positive native",()=>validateCoverage(run,root));\nconst stagepath=resolve(root,run.coverage_discovery_ref);\nconst a=JSON.parse(readFileSync(stagepath,"utf8"));\nconst test=(caseName,mutate,expected)=>{\n const x=structuredClone(a);mutate(x);\n const p=stagepath+".negative_test.json";writeFileSync(p,JSON.stringify(x));\n try {validateCoverage({...run,coverage_discovery_ref:run.coverage_discovery_ref+".negative_test.json"},root);throw Error("unexpected PASS: "+caseName)}\n catch(e){if(e.code!==expected){console.error("wrong rejection for "+caseName+":",e.code,e.message);process.exitCode=1}else console.log("PASS negative "+caseName+": "+e.code)}\n finally{rmSync(p,{force:true})}\n};\ntest("missing original candidate terminal",x=>{x.terminal_discovery_disposition_ledger.pop()},"BLOCKED_COVERAGE_LEDGER");\ntest("missing mandatory region",x=>{delete x.regional_coverage_matrix.korea},"BLOCKED_COVERAGE_AXIS");\ntest("stale full binding",x=>{x.base_full_blob_sha="0000000000000000000000000000000000000000"},"BLOCKED_COVERAGE_BINDING");\nif(!process.exitCode)console.log("PASS: standalone native 0.0D+0.0C stage-gates and 3 negative controls");\n',encoding='utf-8')
  args={'base_main_commit_sha':MAIN,'base_full_blob_sha':FULL,'document_universe_manifest_ref':DOCREF,'coverage_discovery_ref':STAGE_PATH.relative_to(ROOT).as_posix()}
  (RUN/'STAGE_0_0C_SELECTOR_RUN_MANIFEST.json').write_text(json.dumps(args,indent=2)+'\n')
  p=subprocess.run(['node',str(harness),str((RUN/'STAGE_0_0C_SELECTOR_RUN_MANIFEST.json').resolve())],cwd=ROOT,capture_output=True,text=True,timeout=180)
  print(p.stdout[-10000:]);print(p.stderr[-10000:],file=sys.stderr)
  if p.returncode:raise RuntimeError(f'native 0.0D/0.0C validation exit={p.returncode}')
  receipt={'status':'PASS','stage':'0.0C','date_kst':'2026-10-26','base_main_commit_sha':MAIN,'base_full_blob_sha':FULL,'base_lean_blob_sha':LEAN,'r37_stage_0_0d_source':'same_action_replayed_native_preflight','validator_source_main_sha':hashlib.sha256(src.encode()).hexdigest(),'minimal_payload_sha256':PAYLOAD_SHA256,'candidate_count':len(ids),'terminal_count':len(tid),'native_gate_result':'PASS','negative_controls':'3/3_EXPECTED_REJECTIONS','full_production_card_run_verification':'NOT_RUN_BECAUSE_STAGE_A_SELECTOR_ONLY','cards_written':0,'publication_authorized':False}
  (RUN/'STAGE_0_0C_NATIVE_POSITIVE_RECEIPT.json').write_text(json.dumps(receipt,indent=2)+'\n')
 finally:
  exported.unlink(missing_ok=True);harness.unlink(missing_ok=True)

if __name__=='__main__':main()
